create table emdb_notification.ingest (created_at timestamp(6) with time zone not null, correlation_id uuid not null, id uuid not null, event_type varchar(20) not null check ((event_type in ('SUBMITTED','STARTED','PROGRESSED','COMPLETED','FAILED'))), mediaType varchar(255) not null check ((mediaType in ('MOVIE','PERSON','SERIES'))), message varchar(255) not null, primary key (id));
